// ERPNext signs the raw body: X-ilL-Signature = lowercase hex HMAC-SHA256 with the shared
// secret ("sha256=" prefix accepted). A blank secret never verifies, so a missing variable
// answers 401 instead of calling EasyPost unsigned.
const crypto = require('crypto');
const secret = $vars.SHIPPING_WEBHOOK_SECRET; // same value as ilL-Shipping-Settings webhook secret

const item = $input.first();
let rawBody;
if (item.binary && item.binary.data) {
  // rawBody: true puts the exact bytes in binary.data (inline base64, or a stored file id).
  rawBody = item.binary.data.id
    ? await this.helpers.getBinaryDataBuffer(0, 'data')
    : Buffer.from(item.binary.data.data, 'base64');
} else {
  rawBody = Buffer.from(JSON.stringify(item.json.body || {}), 'utf8');
}
const headers = item.json.headers || {};
const provided = String(headers['x-ill-signature'] || headers['X-ilL-Signature'] || '')
  .trim().toLowerCase().replace(/^sha256=/, '');

let signatureOk = false;
if (secret && provided) {
  const expected = crypto.createHmac('sha256', String(secret)).update(rawBody).digest('hex');
  const a = Buffer.from(provided);
  const b = Buffer.from(expected);
  signatureOk = a.length === b.length && crypto.timingSafeEqual(a, b);
}

let request = null;
if (signatureOk) {
  try { request = JSON.parse(rawBody.toString('utf8')); } catch (e) { request = null; }
}
return [{ json: { signature_ok: signatureOk, request } }];

// Route the signed request: rate | buy | void. Anything else answers bad_request.
// Addresses are reduced to the EasyPost Address fields, dropping blanks.
const req = $input.first().json.request;
const badRequest = message => [{ json: { route: 'bad_request', response: { ok: false, error: 'bad_request', message } } }];
if (!req || typeof req !== 'object' || Array.isArray(req)) return badRequest('Request body is not a JSON object');

const action = String(req.action || '').trim().toLowerCase();
if (!['rate', 'buy', 'void'].includes(action)) return badRequest(`Unknown action "${req.action || ''}"; expected rate, buy or void`);

const FIELDS = ['name', 'company', 'street1', 'street2', 'city', 'state', 'zip', 'country', 'phone', 'email'];
const toEasyPostAddress = a => {
  const out = {};
  for (const f of FIELDS) {
    const v = a && a[f];
    if (v !== undefined && v !== null && String(v).trim() !== '') out[f] = String(v).trim();
  }
  return out;
};
const request = { ...req, action };

if (action === 'rate') {
  if (!req.carrier || !req.service) return badRequest('rate needs carrier and service');
  request.from_address = toEasyPostAddress(req.from_address);
  request.to_address = toEasyPostAddress(req.to_address);
  for (const [label, a] of [['from_address', request.from_address], ['to_address', request.to_address]]) {
    if (!a.street1 || !a.city || !a.zip || !a.country) return badRequest(`${label} needs street1, city, zip and country`);
  }
  const parcels = Array.isArray(req.parcels) ? req.parcels : [];
  if (!parcels.length) return badRequest('rate needs at least one parcel');
  for (const p of parcels) {
    const dims = ['length_in', 'width_in', 'height_in', 'weight_lb'].map(k => Number(p && p[k]));
    if (!p || !p.row || dims.some(d => !(d > 0))) {
      return badRequest(`Parcel ${(p && p.row) || '?'} needs a row and a positive length, width, height and weight`);
    }
  }
} else {
  if (!/^order_[A-Za-z0-9]+$/.test(String(req.easypost_id || ''))) {
    return badRequest(`${action} needs easypost_id, the EasyPost order id from the rate step`);
  }
  if (action === 'buy' && !(req.carrier && (req.service_selected || req.service))) {
    return badRequest('buy needs carrier and service_selected (or service)');
  }
}
return [{ json: { route: action, request } }];

// EasyPost HTTP nodes run with fullResponse + neverError, so an API error arrives here as
// { statusCode, body: { error: { code, message, errors } } }. A transport failure (timeout,
// DNS) arrives as { error } because the node continues on error.
const easypostBody = res => {
  let body = res && res.body;
  if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { /* keep text */ } }
  return body;
};
const easypostFailure = res => {
  const status = Number((res && res.statusCode) || 0);
  if (status >= 200 && status < 300) return null;
  const body = easypostBody(res);
  const err = (body && typeof body === 'object' && body.error) || {};
  const transport = res && res.error;
  const message = err.message
    || (transport && (typeof transport === 'string' ? transport : transport.message))
    || (typeof body === 'string' && body.trim() ? body.trim().slice(0, 300) : '')
    || `EasyPost returned HTTP ${status || 'no response'}`;
  const messages = (Array.isArray(err.errors) ? err.errors : [])
    .map(e => (typeof e === 'string' ? e : [e.field, e.message].filter(Boolean).join(': ')))
    .filter(Boolean);
  return { status, code: String(err.code || ''), message: String(message), messages };
};
const easypostError = f => ({ response: { ok: false, error: 'easypost_error', message: f.message, messages: f.messages } });

// Verified with verify: ["delivery"] (not verify_strict), so a failed verification is a
// 200 with verifications.delivery.success === false.
const res = $input.first().json;
const request = $('Validate Request').first().json.request;
const failure = easypostFailure(res);
if (failure) return [{ json: easypostError(failure) }];

const address = easypostBody(res) || {};
const delivery = (address.verifications && address.verifications.delivery) || {};
const messages = (delivery.errors || [])
  .map(e => (typeof e === 'string' ? e : e.message || e.code))
  .filter(Boolean);
if (delivery.success === false) {
  return [{ json: { response: {
    ok: false,
    error: 'address_invalid',
    message: messages[0] || 'EasyPost could not verify the delivery address',
    messages,
  } } }];
}
if (!address.id) return [{ json: easypostError({ message: 'EasyPost returned no address id', messages: [] }) }];
return [{ json: {
  request,
  address: { id: address.id, verified: delivery.success === true, residential: address.residential === true, messages },
} }];

// One EasyPost shipment per parcel; the parcel row is the shipment reference so tracking
// numbers map back to boxes. This is the ONE place pounds become ounces (1 decimal).
const { request, address } = $input.first().json;
const round1 = n => Math.round(n * 10) / 10;
const order = {
  reference: request.shipment || request.reference,
  from_address: request.from_address, // created inline
  to_address: { id: address.id }, // the verified address
  shipments: request.parcels.map(p => ({
    reference: String(p.row),
    parcel: {
      length: Number(p.length_in),
      width: Number(p.width_in),
      height: Number(p.height_in),
      weight: Math.max(0.1, round1(Number(p.weight_lb) * 16)), // ounces
    },
    options: { label_format: 'PDF', additional_handling: Boolean(p.additional_handling) },
  })),
};
const carrierAccount = String(request.carrier_account_id || '').trim();
if (carrierAccount) order.carrier_accounts = [{ id: carrierAccount }];
return [{ json: { order, request, address } }];

