// Order rates: we assume order.rates holds one Rate per carrier+service, already totalled
// across every shipment in the order. In case EasyPost instead lists one Rate per shipment
// (order.rates spans two or more distinct shipment_ids), the rates are summed per
// carrier+service and a service not offered for every shipment is dropped. If order.rates
// is empty, the totals are built the same way from shipments[].rates. delivery_days is the
// slowest box.
const res = $input.first().json;
const { request, address } = $('Build Order').first().json;
const failure = easypostFailure(res);
if (failure) return [{ json: easypostError(failure) }];

const order = easypostBody(res) || {};
const shipments = order.shipments || [];
const shipmentIds = shipments.map(s => s.id).filter(Boolean);
const norm = v => String(v || '').trim().toLowerCase();
const round2 = n => Math.round(n * 100) / 100;

function totals(rateList, perShipment) {
  const groups = new Map();
  for (const r of rateList) {
    const key = `${norm(r.carrier)}|${norm(r.service)}`;
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key).push(r);
  }
  const out = [];
  for (const list of groups.values()) {
    const byShipment = new Map();
    for (const r of list) byShipment.set(r.shipment_id || '', r);
    let parts = [list[0]];
    if (perShipment && shipmentIds.length) {
      if (shipmentIds.some(id => !byShipment.has(id))) continue; // not offered for every box
      parts = shipmentIds.map(id => byShipment.get(id));
    }
    const days = parts.map(r => Number(r.delivery_days)).filter(d => d > 0);
    out.push({
      carrier: list[0].carrier,
      service: list[0].service,
      amount: round2(parts.reduce((sum, r) => sum + Number(r.rate || 0), 0)),
      currency: list[0].currency || 'USD',
      delivery_days: days.length ? Math.max(...days) : null,
    });
  }
  return out.sort((a, b) => a.amount - b.amount);
}

const orderRates = order.rates || [];
const perShipmentRates = shipmentIds.length > 1
  && new Set(orderRates.map(r => r.shipment_id).filter(Boolean)).size > 1;
let rates = totals(orderRates, perShipmentRates);
if (!rates.length) {
  rates = totals(shipments.flatMap(s => (s.rates || []).map(r => ({ ...r, shipment_id: r.shipment_id || s.id }))), true);
}

const messages = (order.messages || [])
  .map(m => (typeof m === 'string' ? m : [m.carrier, m.message].filter(Boolean).join(': ')))
  .filter(Boolean);
const service = address.residential && request.residential_service ? request.residential_service : request.service;
const rate = rates.find(r => norm(r.carrier) === norm(request.carrier) && norm(r.service) === norm(service));
if (!rate) {
  const available = rates.map(r => `${r.carrier} ${r.service}`);
  return [{ json: { response: {
    ok: false,
    error: 'no_rate',
    easypost_id: order.id || null,
    message: `No ${request.carrier} ${service} rate for this shipment. Available: ${available.join(', ') || 'none'}`,
    messages,
    available,
    rates,
  } } }];
}
return [{ json: { response: {
  ok: true,
  easypost_id: order.id,
  rate,
  rates,
  address: { verified: address.verified, residential: address.residential, messages: address.messages },
  messages,
} } }];

