  const messages = (Array.isArray(err.errors) ? err.errors : [])
    .map(e => (typeof e === 'string' ? e : [e.field, e.message].filter(Boolean).join(': ')))
    .filter(Boolean);
  return { status, code: String(err.code || ''), message: String(message), messages };
};
const easypostError = f => ({ response: { ok: false, error: 'easypost_error', message: f.message, messages: f.messages } });

// A retry after a timeout must never buy twice: if EasyPost says the order already has
// postage, read the order back instead. EasyPost documents no single code for this on
// Orders, so it is detected by error code (contains ALREADY or POSTAGE.EXISTS, as in
// SHIPMENT.POSTAGE.EXISTS) or by message ("already purchased/bought", "postage exists").
const res = $input.first().json;
const failure = easypostFailure(res);
if (!failure) return [{ json: { order: easypostBody(res) } }];
const text = `${failure.code} ${failure.message} ${failure.messages.join(' ')}`;
const alreadyBought = /ALREADY|POSTAGE\.EXISTS/i.test(failure.code)
  || /already\s+(been\s+)?(purchased|bought)|postage\s+(already\s+)?exists|already\s+has\s+postage/i.test(text);
if (alreadyBought) return [{ json: { refetch: true } }];
return [{ json: easypostError(failure) }];

