    || (typeof body === 'string' && body.trim() ? body.trim().slice(0, 300) : '')
    || `EasyPost returned HTTP ${status || 'no response'}`;
  const messages = (Array.isArray(err.errors) ? err.errors : [])
    .map(e => (typeof e === 'string' ? e : [e.field, e.message].filter(Boolean).join(': ')))
    .filter(Boolean);
  return { status, code: String(err.code || ''), message: String(message), messages };
};
const easypostError = f => ({ response: { ok: false, error: 'easypost_error', message: f.message, messages: f.messages } });

// Map each bought EasyPost shipment back to its Shipment Parcel row (shipment.reference),
// in the order ERPNext listed the parcels. The first box carries the master number.
const request = $('Validate Request').first().json.request;
const input = $input.first().json;
if (input.response) return [{ json: { response: input.response } }]; // buy failed
let order = input.order;
if (!order) {
  // Came from Get Bought Order (the already-purchased path).
  const failure = easypostFailure(input);
  if (failure) return [{ json: easypostError(failure) }];
  order = easypostBody(input) || {};
}
const rowOrder = (request.parcels || []).map(p => String(p.row));
const position = s => { const i = rowOrder.indexOf(String(s.reference)); return i < 0 ? rowOrder.length : i; };
const shipments = [...(order.shipments || [])].sort((a, b) => position(a) - position(b));
const unbought = shipments.filter(s => !s.tracking_code);
if (!shipments.length || unbought.length) {
  const which = unbought.length ? unbought.map(s => s.reference || s.id).join(', ') : 'any parcel';
  return [{ json: easypostError({ message: `EasyPost order ${order.id || request.easypost_id} has no label for ${which}`, messages: [] }) }];
}

const first = shipments[0];
const firstRate = first.selected_rate || {};
const round2 = n => Math.round(n * 100) / 100;
return [{ json: { response: {
  ok: true,
  easypost_id: order.id || request.easypost_id,
  carrier: firstRate.carrier || request.carrier,
  service: firstRate.service || request.service_selected || request.service,
  amount: round2(shipments.reduce((sum, s) => sum + Number((s.selected_rate || {}).rate || 0), 0)),
  currency: firstRate.currency || 'USD',
  master_tracking: first.tracking_code,
  tracking_url: (first.tracker && first.tracker.public_url) || null,
  parcels: shipments.map(s => ({
    row: s.reference || null,
    tracking_number: s.tracking_code,
    label_url: (s.postage_label && (s.postage_label.label_pdf_url || s.postage_label.label_url)) || null,
    easypost_shipment_id: s.id,
  })),
} } }];

