// Refund every bought label (a shipment with a tracking_code). Labels already refunded or
// with a refund submitted are reported as they stand, so a retried void is harmless.
const res = $input.first().json;
const failure = easypostFailure(res);
if (failure) return [{ json: easypostError(failure) }];
const order = easypostBody(res) || {};
const bought = (order.shipments || []).filter(s => s.tracking_code);
if (!bought.length) {
  return [{ json: easypostError({ message: `EasyPost order ${order.id} has no bought labels to void`, messages: [] }) }];
}
const done = s => ['submitted', 'refunded'].includes(String(s.refund_status || '').toLowerCase());
const previous = bought.filter(done).map(s => ({ easypost_shipment_id: s.id, status: s.refund_status }));
const pending = bought.filter(s => !done(s));
if (!pending.length) {
  return [{ json: { response: {
    ok: false,
    error: 'already_refunded',
    message: 'Every label on this order is already refunded or has a refund submitted',
    refunds: previous,
  } } }];
}
return pending.map(s => ({ json: { easypost_shipment_id: s.id, tracking_code: s.tracking_code, previous } }));

