// One Refund Shipment result per planned shipment, in the same order. A partial failure
// answers easypost_error (ERPNext keeps the labels Bought); the retry skips the refunds
// already submitted.
const planned = $('Plan Refunds').all().map(i => i.json);
const refunds = [...((planned[0] && planned[0].previous) || [])];
const failed = [];
$input.all().forEach((item, i) => {
  const id = (planned[i] || {}).easypost_shipment_id;
  const failure = easypostFailure(item.json);
  if (failure) { failed.push(`${id}: ${failure.message}`); return; }
  const shipment = easypostBody(item.json) || {};
  refunds.push({ easypost_shipment_id: shipment.id || id, status: shipment.refund_status || 'submitted' });
});
if (failed.length) {
  return [{ json: { response: {
    ok: false,
    error: 'easypost_error',
    message: `Refund failed for ${failed.join('; ')}`,
    messages: failed,
    refunds,
  } } }];
}
return [{ json: { response: { ok: true, refunds } } }];
